const CACHE="mono-mock-v62";const ASSETS=["./secret-visibility.js?v=62","./launch.js?v=62","./apple-touch-icon.png?v=62","./icon-192.png?v=62","./auth-gate.js?v=62","./auth.css?v=62","./cabinets.js?v=62","./assets/reference/limits-sticker-hq.png","./assets/reference/market-eyes-hq.png","./assets/reference/market-owl-hq.png","./sharp-icons.js?v=62","./bank-detail.js?v=62","./bank-detail.css?v=62","./assets/reference/transfer-pattern.svg","./icon-catalog.js?v=62","./mobile-stability.js?v=62","./mobile-stability.css?v=62","./pull-refresh.js?v=62","./hosted-storage.js?v=62","./card-stable.js?v=62","./card-stable.css?v=62","./profile-pwa.js?v=62","./profile-pwa.css?v=62","./history-glass.js?v=62","./history-glass.css?v=62","./faithful.css?v=62","./faithful-motion.js?v=62","./faithful-entry.js?v=62","./receipt-links.js?v=62","./native-reference.js?v=62","./native-reference.css?v=62","./reference-fidelity.js?v=62","./reference-fidelity.css?v=62","./continuity.js?v=62","./continuity.css?v=62","./motion.js?v=62","./motion.css?v=62","./recording.js?v=62","./recording.css?v=62","./interactions.js?v=62","./interactions.css?v=62","./surfaces.js?v=62","./surfaces.css?v=62","./refinement.css?v=62","./refinement.js?v=62","./reference.css?v=62","./experience.js?v=62","./style.css?v=62","./app.js?v=62","./manifest.json","./icon.svg","./icon.png","./pwa-runtime.js?v=62","./pwa-runtime.css?v=62","./admin-manifest.json"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mono-mock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(request.mode==='navigate'){event.respondWith(fetch(new Request(request,{cache:'no-store'})).catch(()=>new Response('<!doctype html><meta name="viewport" content="width=device-width"><style>html{background:#161616;color:white;font:18px system-ui;padding:24px}</style>Потрібне з’єднання з інтернетом. Відкрийте застосунок повторно після підключення.',{headers:{'Content-Type':'text/html; charset=utf-8'}})));return}
 event.respondWith(fetch(request).then(response=>{if(response.ok&&url.pathname.startsWith('/assets/')){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(request,copy)))}return response}).catch(()=>caches.match(request).then(cached=>cached||Response.error())))
});
